// 使用 LUT 进行 sigmoid 计算
float lut_sigmoid(float x) {
    // 限定 x 的范围为 [-8, 8]
    if (x < -16.0f) x = -16.0f;
    if (x > 16.0f)  x = 16.0f;
    // 将 x 映射到 0 ~ (LUT_SIZE-1)
    float index_f = (x + 16.0f) * ((float)(LUT_SIZE - 1) / 32.0f);
    int index = (int) index_f;
    if (index < 0) index = 0;
    if (index >= LUT_SIZE) index = LUT_SIZE - 1;
    return sigmoid_LUT[index];
}
float lut_tanh(float x) {
    // 限定 x 的范围为 [-8, 8]
    if (x < -16.0f) x = -16.0f;
    if (x > 16.0f)  x = 16.0f;
    // 将 x 映射到 0 ~ (LUT_SIZE-1)
    float index_f = (x + 16.0f) * ((float)(LUT_SIZE - 1) / 32.0f);
    int index = (int) index_f;
    if (index < 0) index = 0;
    if (index >= LUT_SIZE) index = LUT_SIZE - 1;
    return tanh_LUT[index];
}
// 简单的量化函数，根据给定 bitwidth 将 x 限制到 [-max_range, max_range] 内，并量化为离散值
float quantize(float x, int bitwidth) {
    int levels = (1 << bitwidth);  // 离散级数：例如 4bit -> 16 级
    float max_range = 16.0f;          // 假设输入数据范围为 [-1, 1]
    float step = (2 * max_range) / (levels - 1);
    if (x > max_range) x = max_range;
    if (x < -max_range) x = -max_range;
    int q = (int)((x + max_range) / step + 0.5f);
    float quantized = q * step - max_range;
    return quantized;
}

// LSTM 单元顶层函数（简化示例版）：
// 对于每个输入，先做量化，再用 LUT 计算 sigmoid，然后更新内部状态（这里简单累加）。
void lstm_unit(float input_data[INPUT_SIZE],
               float output_data[OUTPUT_SIZE],
               int bitwidth) {
#pragma HLS INTERFACE ap_memory port=input_data
#pragma HLS INTERFACE ap_memory port=output_data
#pragma HLS INTERFACE s_axilite port=bitwidth
#pragma HLS INTERFACE s_axilite port=return

    float state[STATE_SIZE];
	#pragma HLS ARRAY_PARTITION variable=state complete

    // 初始化状态为 0
    for (int i = 0; i < STATE_SIZE; i++) {
		#pragma HLS PIPELINE
        state[i] = 0.0f;
    }

    // 对每个输入进行处理（假设一次只处理一个时间步，简化 LSTM 内部操作）
    for (int i = 0; i < INPUT_SIZE && i < STATE_SIZE; i++) {
		#pragma HLS PIPELINE
        float in_val = input_data[i];
        // 根据动态位宽对输入进行量化
        float quantized_val = quantize(in_val, bitwidth);
        // 使用 LUT 计算 sigmoid（模拟门控计算）
        float gate = lut_sigmoid(quantized_val);
        // 简单更新状态（实际 LSTM 包括多门机制，这里仅做示意）
        state[i] = state[i] + gate;
    }

    // 将内部状态作为输出
    for (int i = 0; i < OUTPUT_SIZE && i < STATE_SIZE; i++) {
		#pragma HLS PIPELINE
        output_data[i] = state[i];
    }
}
